        assertEquals(true, result.contains("/** Begin line maps. **/"));
        assertEquals(true, result.contains("\"file\" : \"test.js\""));
        assertEquals(true, result.contains("\"count\": 2"));
        assertEquals(true, result.contains("/** Begin file information. **/"));
        assertEquals(true, result.contains("/** Begin mapping definitions. **/"));
        assertEquals(true, result.contains("[\"a.js\", 1, 34]"));
